seq = ''.join(l.strip() for l in open('region.fasta') if not l.startswith('>') and l.strip())
comp = str.maketrans('ACGT','TGCA')
rc = lambda s: s.translate(comp)[::-1]

def gc(s): return 100*(s.count('G')+s.count('C'))/len(s)

codon_table = {}
bases='TCAG'
aas='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
i=0
for b1 in bases:
    for b2 in bases:
        for b3 in bases:
            codon_table[b1+b2+b3]=aas[i]; i+=1

def translate(s):
    return ''.join(codon_table.get(s[i:i+3],'X') for i in range(0,len(s)-2,3))

# find ORFs in all 6 frames
for strand, s in (('+',seq),('-',rc(seq))):
    for frame in range(3):
        prot = translate(s[frame:])
        print(f"=== strand {strand} frame {frame} ===")
        # ORFs
        pos=0
        for m in re.finditer(r'[^*]+', prot):
            orf = m.group()
            start = m.start()
